<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{Aircraft,Flight,Reservation}; use Illuminate\Http\Request;
class AirlineApiController extends Controller {
 public function dashboard(){return response()->json(['aircraft'=>Aircraft::count(),'flights'=>Flight::count(),'reservations'=>Reservation::count(),'latest_flights'=>Flight::with('aircraft')->latest('departure_at')->take(5)->get()]);}
 public function aircraftIndex(){return Aircraft::withCount('flights')->paginate(15);} public function aircraftStore(Request $r){$d=$r->validate(['registration_number'=>'required|string|max:50|unique:aircraft','model'=>'required|string|max:100','manufacturer'=>'required|string|max:100','capacity'=>'required|integer|min:1','status'=>'required|string|max:30']);return response()->json(Aircraft::create($d),201);} public function aircraftShow(Aircraft $aircraft){return $aircraft->load('flights');} public function aircraftUpdate(Request $r,Aircraft $aircraft){$d=$r->validate(['registration_number'=>'sometimes|required|string|max:50|unique:aircraft,registration_number,'.$aircraft->id,'model'=>'sometimes|required|string|max:100','manufacturer'=>'sometimes|required|string|max:100','capacity'=>'sometimes|required|integer|min:1','status'=>'sometimes|required|string|max:30']);$aircraft->update($d);return $aircraft->fresh();} public function aircraftDelete(Aircraft $aircraft){if($aircraft->flights()->exists())return response()->json(['message'=>'هواپیما دارای پرواز است.'],409);$aircraft->delete();return response()->json(['message'=>'حذف شد']);}
 public function flightIndex(){return Flight::with('aircraft')->withCount('reservations')->paginate(15);} public function flightStore(Request $r){$d=$r->validate(['flight_number'=>'required|string|max:50','origin'=>'required|string|max:100','destination'=>'required|string|max:100|different:origin','departure_at'=>'required|date','arrival_at'=>'required|date|after:departure_at','aircraft_id'=>'required|exists:aircraft,id','status'=>'required|string|max:30']);return response()->json(Flight::create($d)->load('aircraft'),201);} public function flightShow(Flight $flight){return $flight->load(['aircraft','reservations']);} public function flightUpdate(Request $r,Flight $flight){$d=$r->validate(['flight_number'=>'sometimes|required|string|max:50','origin'=>'sometimes|required|string|max:100','destination'=>'sometimes|required|string|max:100','departure_at'=>'sometimes|required|date','arrival_at'=>'sometimes|required|date|after:departure_at','aircraft_id'=>'sometimes|required|exists:aircraft,id','status'=>'sometimes|required|string|max:30']);$flight->update($d);return $flight->fresh()->load('aircraft');} public function flightDelete(Flight $flight){if($flight->reservations()->exists())return response()->json(['message'=>'پرواز دارای رزرو است.'],409);$flight->delete();return response()->json(['message'=>'حذف شد']);}
 public function reservationIndex(){return Reservation::with('flight')->paginate(15);} public function reservationStore(Request $r){$d=$r->validate(['passenger_name'=>'required|string|max:120','passenger_email'=>'nullable|email|max:150','seat_number'=>'required|string|max:10','flight_id'=>'required|exists:flights,id','status'=>'required|string|max:30']);$flight=Flight::with('aircraft')->findOrFail($d['flight_id']);if(Reservation::where('flight_id',$flight->id)->where('seat_number',$d['seat_number'])->exists())return response()->json(['message'=>'این صندلی قبلاً رزرو شده است.'],409);if(Reservation::where('flight_id',$flight->id)->count()>=$flight->aircraft->capacity)return response()->json(['message'=>'ظرفیت پرواز تکمیل است.'],422);return response()->json(Reservation::create($d)->load('flight'),201);} public function reservationShow(Reservation $reservation){return $reservation->load('flight');} public function reservationUpdate(Request $r,Reservation $reservation){$d=$r->validate(['passenger_name'=>'sometimes|required|string|max:120','passenger_email'=>'nullable|email|max:150','seat_number'=>'sometimes|required|string|max:10','flight_id'=>'sometimes|required|exists:flights,id','status'=>'sometimes|required|string|max:30']);$flightId=$d['flight_id']??$reservation->flight_id;$seat=$d['seat_number']??$reservation->seat_number;if(Reservation::where('flight_id',$flightId)->where('seat_number',$seat)->where('id','!=',$reservation->id)->exists())return response()->json(['message'=>'این صندلی قبلاً رزرو شده است.'],409);$reservation->update($d);return $reservation->fresh()->load('flight');} public function reservationDelete(Reservation $reservation){$reservation->delete();return response()->json(['message'=>'رزرو حذف شد']);}
}
